(function(root){
 'use strict';
 const J=root.ND_JOURNAL_MODEL,states=new Map(),h=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const icon=(name,cls='')=>'<img class="journal-icon '+cls+'" src="assets/journal-ui/icons/'+name+'.png" alt="" aria-hidden="true">';
 const key=()=>typeof cloudRecord!=='undefined'&&cloudRecord?cloudRecord.id:'local';
 function state(){const k=key();if(!states.has(k))states.set(k,{query:'',tag:'',sort:'new',selected:null,detail:false,scroll:0,closed:new Set(),draft:null});return states.get(k);}
 const rows=()=>J.normalize(card.notes),readonly=()=>!canEdit;
 function tags(r,compact=false){const shown=compact?r.tags.slice(0,2):r.tags;return shown.map(t=>'<span class="journal-tag">'+h(t)+'</span>').join('')+(compact&&r.tags.length>2?'<span class="journal-tag">+'+(r.tags.length-2)+'</span>':'');}
 function listMarkup(){const s=state(),all=rows(),visible=J.select(all,s);if(!visible.some(x=>x.id===s.selected))s.selected=visible[0]?.id||null;return visible.length?J.groups(visible).map(g=>'<details class="journal-group" data-journal-group="'+h(g.key)+'" '+(s.closed.has(g.key)?'':'open')+'><summary><span>'+h(g.title)+'</span><small>'+g.rows.length+' '+plural(g.rows.length)+'</small></summary><div>'+g.rows.map(r=>'<button class="journal-row '+(s.selected===r.id?'is-selected':'')+'" data-journal-select="'+h(r.id)+'" aria-pressed="'+(s.selected===r.id)+'">'+icon(r.pinned?'pin':'note')+'<span class="journal-row-copy"><strong>'+h(r.title)+'</strong><span class="journal-row-meta">'+(r.tags.length?tags(r,true):h((r.location||r.npc||r.text).slice(0,95)))+'</span></span><time>'+h(J.date(r.createdAt))+'</time></button>').join('')+'</div></details>').join(''):'<div class="journal-empty">'+icon('journal')+'<h2>'+(all.length?'По этому запросу записей не найдено.':'Журнал пока пуст')+'</h2><p>'+(all.length?'Попробуй другой запрос или сбрось фильтры.':'Здесь будут твои встречи, зацепки и последствия решений.')+'</p>'+(all.length?'<button data-journal-reset>Сбросить поиск и фильтры</button>':canEdit?'<button class="yellow" data-journal-new>Создать первую запись</button>':'')+'</div>';}
 function plural(n){return n%10===1&&n%100!==11?'запись':n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?'записи':'записей';}
 function attachment(a){const url=J.https(a.url);if(!url)return '';return '<a class="journal-attachment" href="'+h(url)+'" target="_blank" rel="noopener noreferrer">'+(a.kind==='image'?'<img loading="lazy" referrerpolicy="no-referrer" src="'+h(url)+'" alt="'+h(a.name)+'">':icon('attachment'))+'<span>'+h(a.name)+'</span><small>Открыть ↗</small></a>';}
 function detailMarkup(){const r=rows().find(x=>x.id===state().selected);if(!r)return '<div class="journal-empty">'+icon('note')+'<p>Выбери запись в архиве</p></div>';return '<div class="journal-detail-top"><button class="journal-back" data-journal-back>← Назад</button><h2>'+h(r.title)+'</h2><time>'+h(J.date(r.createdAt))+'</time></div><div class="journal-detail-body">'+(r.tags.length?'<div class="journal-tags">'+tags(r)+'</div>':'')+((r.location||r.npc)?'<dl class="journal-metadata">'+(r.location?'<div><dt>'+icon('location')+'Локация</dt><dd>'+h(r.location)+'</dd></div>':'')+(r.npc?'<div><dt>'+icon('contact')+'Контакт / NPC</dt><dd>'+h(r.npc)+'</dd></div>':'')+'</dl>':'')+'<div class="journal-text">'+h(r.text)+'</div>'+(r.attachments.length?'<section class="journal-attachments"><h3>'+icon('attachment')+'Вложения ('+r.attachments.length+')</h3><div>'+r.attachments.map(attachment).join('')+'</div></section>':'')+'<details class="journal-dates"><summary>Даты записи</summary><p>Создано: '+h(J.realDate(r.createdAt))+'</p>'+(r.updatedAt?'<p>Изменено: '+h(J.date(r.updatedAt))+'</p>':'')+'</details>'+(canEdit?'<div class="journal-actions"><button data-journal-edit="'+h(r.id)+'">'+icon('edit')+'Редактировать</button><button data-journal-pin="'+h(r.id)+'">'+icon('pin')+(r.pinned?'Открепить':'Закрепить')+'</button><button class="journal-delete" data-journal-delete="'+h(r.id)+'">'+icon('delete')+'Удалить</button></div>':'')+'</div>';}
 function renderJournal(){const s=state(),all=rows(),allTags=[...new Set(all.flatMap(x=>x.tags))].sort((a,b)=>a.localeCompare(b,'ru'));if(s.tag&&!allTags.includes(s.tag))s.tag='';const list=listMarkup();return '<section class="journal-ui '+(s.detail?'is-detail':'')+'" aria-label="Личный журнал"><header class="journal-heading"><div><h1>Журнал</h1><p>Личные заметки, контакты и последствия решений.</p></div>'+(canEdit?'<button class="yellow journal-new" data-journal-new>'+icon('add')+'Новая запись</button>':'')+'</header><div class="journal-tools"><label class="journal-search">'+icon('search')+'<span class="dossier-visually-hidden">Поиск по записям</span><input id="journal-search" type="search" placeholder="Поиск по записям…" value="'+h(s.query)+'" maxlength="200"></label><label><span class="dossier-visually-hidden">Фильтр по тегам</span><select id="journal-tag"><option value="">Все теги</option>'+allTags.map(t=>'<option '+(s.tag===t?'selected':'')+' value="'+h(t)+'">'+h(t)+'</option>').join('')+'</select></label><label><span class="dossier-visually-hidden">Сортировка записей</span><select id="journal-sort"><option value="new" '+(s.sort==='new'?'selected':'')+'>Сначала новые</option><option value="old" '+(s.sort==='old'?'selected':'')+'>Сначала старые</option><option value="title" '+(s.sort==='title'?'selected':'')+'>По названию</option></select></label></div><div class="journal-workspace"><section class="journal-archive" aria-label="Архив записей">'+list+'</section><article class="journal-detail" aria-label="Просмотр записи">'+detailMarkup()+'</article></div></section>';}
 function requireEdit(){if(readonly())throw Error('Карточка открыта только для просмотра');}
 function commit(nextRows){requireEdit();const next=E.clone(card);next.notes=J.normalize(nextRows);card=E.validate(next,D);changed();render();}
 function saveEntry(input,options){requireEdit();const next=J.save(card.notes,input,options);const s=state(),chosen=options?.id||next[0].id;if(!options?.id){s.query='';s.tag='';s.sort='new';}else if(!J.select(next,s).some(x=>x.id===chosen)){s.query='';s.tag='';}s.selected=chosen;s.detail=true;commit(next);return s.selected;}
 function pin(id){requireEdit();const all=rows();if(!all.some(x=>x.id===id))throw Error('Запись больше не существует');commit(all.map(x=>x.id===id?{...x,pinned:!x.pinned}:x));}
 function remove(id){requireEdit();const all=rows(),r=all.find(x=>x.id===id);if(!r)throw Error('Запись больше не существует');modal('Удалить запись?', '<p>'+h(r.title)+'</p><p>Запись и ссылки на её вложения будут удалены из журнала.</p><button id="journal-confirm-delete" class="yellow">Удалить запись</button><button id="journal-cancel-delete">Отмена</button>');document.querySelector('#journal-cancel-delete').onclick=closeModal;document.querySelector('#journal-confirm-delete').onclick=()=>{try{requireEdit();commit(rows().filter(x=>x.id!==id));state().detail=false;closeModal();render();}catch(e){notify(e.message);}};}
 function editor(id){requireEdit();const s=state();if(s.draft&&s.draft.id!==id&&isDraftDirty())throw Error('Сначала сохрани или отмени открытый черновик');const old=id?rows().find(x=>x.id===id):null;if(id&&!old)throw Error('Запись больше не существует');if(!s.draft||s.draft.id!==id){const initial={title:old?.title||'',text:old?.text||'',location:old?.location||'',npc:old?.npc||'',tags:(old?.tags||[]).join(', '),attachments:E.clone(old?.attachments||[])};s.draft={id,values:initial,initial:JSON.stringify(initial)};}const d=s.draft.values;
 modal(id?'Редактировать запись':'Новая запись','<form id="journal-editor"><label>Заголовок<input name="title" required maxlength="200" placeholder="Что произошло?" value="'+h(d.title)+'"></label><label>Содержание<textarea name="text" required maxlength="20000" rows="10" placeholder="Опиши события, наблюдения, зацепки или важные детали…">'+h(d.text)+'</textarea></label><div class="journal-editor-meta"><label>Локация<input name="location" maxlength="20000" value="'+h(d.location)+'"></label><label>Контакт / NPC<input name="npc" maxlength="20000" value="'+h(d.npc)+'"></label></div><label>Теги через запятую<input name="tags" maxlength="2600" placeholder="Контакт, Локация, Контракт…" value="'+h(d.tags)+'"></label><div class="journal-tag-presets">'+['Контакт','Локация','Контракт','Улика','Событие','Задача','Риск'].map(t=>'<button type="button" data-journal-preset="'+t+'">'+t+'</button>').join('')+'</div><section class="journal-editor-links"><h3>'+icon('attachment')+'Вложения по HTTPS-ссылке</h3><p>Ссылка должна вести на постоянно доступный файл. Загрузка файлов с устройства пока не поддерживается.</p><div id="journal-draft-links"></div><label>Название вложения<input id="journal-link-name" maxlength="200" placeholder="Название файла или материала"></label><label>HTTPS-ссылка<input id="journal-link-url" type="url" maxlength="2048" placeholder="https://…"></label><label class="journal-image-check"><input id="journal-link-image" type="checkbox"> Показывать превью изображения</label><button type="button" id="journal-add-link">Добавить ссылку</button></section><p id="journal-editor-error" role="alert"></p><div class="journal-editor-buttons"><button type="button" id="journal-cancel">Отмена</button><button class="yellow" type="submit">Сохранить</button></div></form><div id="journal-discard" hidden><p>В записи есть несохранённые изменения. Отменить их?</p><button id="journal-keep-editing">Продолжить редактирование</button><button id="journal-discard-confirm">Не сохранять</button></div>');
 const dialog=document.querySelector('#dialog'),form=document.querySelector('#journal-editor');dialog.classList.add('journal-dialog');const read=()=>{for(const k of ['title','text','location','npc','tags'])d[k]=form.elements.namedItem(k).value;};form.oninput=read;
 const close=()=>{read();if(isDraftDirty()){document.querySelector('#journal-discard').hidden=false;document.querySelector('#journal-keep-editing').focus();}else finish();};const finish=()=>{s.draft=null;dialog.oncancel=null;dialog.classList.remove('journal-dialog');closeModal();};document.querySelector('#close-modal').onclick=close;document.querySelector('#journal-cancel').onclick=close;dialog.oncancel=e=>{e.preventDefault();close();};document.querySelector('#journal-keep-editing').onclick=()=>{document.querySelector('#journal-discard').hidden=true;};document.querySelector('#journal-discard-confirm').onclick=finish;
 document.querySelectorAll('[data-journal-preset]').forEach(b=>b.onclick=()=>{const input=form.elements.namedItem('tags'),values=input.value.split(',').map(x=>x.trim()).filter(Boolean);if(!values.includes(b.dataset.journalPreset))values.push(b.dataset.journalPreset);input.value=values.join(', ');read();});
 const links=()=>{document.querySelector('#journal-draft-links').innerHTML=d.attachments.map((a,i)=>'<div><span>'+h(a.name)+'</span><button type="button" data-journal-link-remove="'+i+'" aria-label="Удалить вложение '+h(a.name)+'">×</button></div>').join('');document.querySelectorAll('[data-journal-link-remove]').forEach(b=>b.onclick=()=>{d.attachments.splice(Number(b.dataset.journalLinkRemove),1);links();});};links();
 document.querySelector('#journal-add-link').onclick=()=>{try{requireEdit();const name=document.querySelector('#journal-link-name'),url=document.querySelector('#journal-link-url'),image=document.querySelector('#journal-link-image');if(!name.value.trim()||!J.https(url.value))throw Error('Укажи название и корректную HTTPS-ссылку');if(d.attachments.length>=20)throw Error('Не более 20 вложений');d.attachments.push({name:name.value.trim(),url:J.https(url.value),kind:image.checked?'image':'link'});name.value='';url.value='';image.checked=false;links();document.querySelector('#journal-editor-error').textContent='';}catch(e){document.querySelector('#journal-editor-error').textContent=e.message;}};
 form.onsubmit=e=>{e.preventDefault();read();try{requireEdit();const input={...d,tags:d.tags.split(',').map(x=>x.trim()).filter(Boolean)};saveEntry(input,{id});finish();}catch(err){document.querySelector('#journal-editor-error').textContent=err.message;}};
 }
 function isDraftDirty(){const d=state().draft;return !!d&&JSON.stringify(d.values)!==d.initial;}
 function refresh(){const archive=document.querySelector('.journal-archive'),detail=document.querySelector('.journal-detail');if(!archive||!detail)return;archive.innerHTML=listMarkup();detail.innerHTML=detailMarkup();bindRows();}
 function safe(fn){return ()=>{try{fn();}catch(e){notify(e.message);}};}
 function bindRows(){document.querySelectorAll('[data-journal-select]').forEach(b=>b.onclick=()=>{const s=state();s.scroll=root.scrollY||0;s.selected=b.dataset.journalSelect;s.detail=true;render();if(root.matchMedia?.('(max-width:767px)').matches)root.scrollTo(0,0);});document.querySelectorAll('[data-journal-group]').forEach(el=>el.ontoggle=()=>{const s=state();if(el.open)s.closed.delete(el.dataset.journalGroup);else s.closed.add(el.dataset.journalGroup);});document.querySelectorAll('[data-journal-edit]').forEach(b=>b.onclick=safe(()=>editor(b.dataset.journalEdit)));document.querySelectorAll('[data-journal-pin]').forEach(b=>b.onclick=safe(()=>pin(b.dataset.journalPin)));document.querySelectorAll('[data-journal-delete]').forEach(b=>b.onclick=safe(()=>remove(b.dataset.journalDelete)));document.querySelectorAll('[data-journal-back]').forEach(b=>b.onclick=()=>{const s=state();s.detail=false;render();root.scrollTo(0,s.scroll);});document.querySelectorAll('[data-journal-new]').forEach(b=>b.onclick=safe(()=>editor()));document.querySelectorAll('[data-journal-reset]').forEach(b=>b.onclick=()=>{const s=state();s.query='';s.tag='';s.sort='new';render();});}
 function bind(){if(typeof tab==='undefined'||tab!=='notes')return;bindRows();const q=document.querySelector('#journal-search'),tag=document.querySelector('#journal-tag'),sort=document.querySelector('#journal-sort');if(q)q.oninput=()=>{state().query=q.value;refresh();};if(tag)tag.onchange=()=>{state().tag=tag.value;refresh();};if(sort)sort.onchange=()=>{state().sort=sort.value;refresh();};}
 root.addEventListener?.('beforeunload',e=>{if(isDraftDirty()){e.preventDefault();e.returnValue='';}});
 root.ND_JOURNAL={render:renderJournal,bind,state,editor,saveEntry,pin,remove,isDraftDirty};
})(typeof window!=='undefined'?window:globalThis);
